import { StrikeHttp } from "./http.js";
import { ApiWalletKey } from "./signer.js";

export type Chain = "cardano" | "ethereum" | "solana";

export interface BuilderSession {
  accountId: string;
  builderCode: string;
  feeShareBps: number;
  apiWalletId: number;
  apiWalletPublicKey: string;
  /** Strike currently issues `9999-12-31T23:59:59Z` (never expires) — the widget enforces its own session lifetime. */
  apiWalletExpiresAt: string;
  address: string;
  chain: Chain;
  connectedAt: number;
}

export interface ConnectParams {
  http: StrikeHttp;
  address: string;
  chain: Chain;
  builderCode: string;
  /** Maximum fee the user approves for this builder (0–100 bps). Shown to the user in the signed message. */
  feeShareBps: number;
  referralCode?: string;
  /** Asks the user's wallet to sign Strike's consent message. */
  signMessage: (message: string) => Promise<string>;
  /** Optionally inspect the message before signing (e.g. to display it). */
  onMessage?: (message: string) => void;
}

/**
 * Screens Strike's consent text before the user's wallet signs it: it must be a plain, readable message
 * (no control or bidirectional-override characters that could hide or reorder text) of sane length.
 * It should also name the API key being bound; if Strike ever stops including it we only warn.
 */
export function checkConsentMessage(message: string, apiPublicKeyHex: string): void {
  if (typeof message !== "string" || !message.trim()) throw new Error("Strike sent an empty message to sign. Not signing.");
  if (message.length > 4096) throw new Error("Strike's message to sign is unexpectedly long. Not signing.");
  // C0 controls except tab/newline/CR, DEL, C1 controls, and Unicode bidi overrides/isolates.
  if (/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F‪-‮⁦-⁩]/.test(message)) {
    throw new Error("Strike's message to sign contains hidden control characters. Not signing.");
  }
  if (!message.toLowerCase().includes(apiPublicKeyHex.toLowerCase())) {
    console.warn("[strike-everywhere] Strike's consent message doesn't name the API key being bound.");
  }
}

/**
 * Builder Connect: creates (or reuses) the user's Strike account and a fresh API wallet bound to the builder code.
 * Strike revokes earlier API wallets for the same account + builder code, so reconnecting rotates the key.
 */
export async function builderConnect(p: ConnectParams): Promise<{ session: BuilderSession; key: ApiWalletKey }> {
  const key = await ApiWalletKey.generate();
  // Strike decodes this body strictly: unknown fields → 400 (verified 2026-10-19: `max_fee_bps` is rejected,
  // `fee_share_bps` is the cap shown in the consent text). `referral_code` is a known field, but Strike rejects a
  // code that doesn't exist with a 400, so if the request fails with it we retry without; the widget then offers
  // the "apply on Strike" link instead.
  const requestSignature = (withReferral: boolean) =>
    p.http.request<{ nonce: string; message_to_sign: string }>("POST", "/auth/builder/request-signature", {
      auth: false,
      body: {
        address: p.address,
        chain: p.chain,
        code: p.builderCode,
        fee_share_bps: p.feeShareBps,
        public_key: key.publicKeyHex,
        ...(withReferral && p.referralCode ? { referral_code: p.referralCode } : {}),
      },
    });
  // Strike refuses connecting the builder's own account to its code (since 2026-10-22); say what to do instead.
  const ownCode = (e: any) =>
    /own builder code/i.test(e?.message ?? "") ? new Error(`This wallet owns the builder code ${p.builderCode}, and Strike doesn't let a builder trade through its own code. Connect a different wallet.`) : e;
  let challenge: { nonce: string; message_to_sign: string };
  try {
    challenge = await requestSignature(true);
  } catch (e: any) {
    if (!p.referralCode || e?.status !== 400 || /own builder code/i.test(e?.message ?? "")) throw ownCode(e);
    challenge = await requestSignature(false).catch((e2) => Promise.reject(ownCode(e2)));
  }
  checkConsentMessage(challenge.message_to_sign, key.publicKeyHex);
  p.onMessage?.(challenge.message_to_sign);
  const walletSignature = await p.signMessage(challenge.message_to_sign);
  let r: any;
  try {
    r = await p.http.request<any>("POST", "/auth/builder/verify-signature", {
      auth: false,
      body: { address: p.address, chain: p.chain, nonce: challenge.nonce, wallet_signature: walletSignature },
    });
  } catch (e: any) {
    // Strike's signature challenge expires after ~3 minutes (mainnet config).
    if (/expir|nonce|challenge/i.test(e?.message ?? "")) throw new Error("The signature request expired (Strike allows a few minutes). Click Sign & connect to get a new one.");
    throw ownCode(e);
  }
  if (r.api_wallet_public_key && r.api_wallet_public_key !== key.publicKeyHex) {
    throw new Error("Strike returned a different API key than the one generated. Aborting.");
  }
  return {
    key,
    session: {
      accountId: r.account_id,
      builderCode: r.builder_code ?? p.builderCode,
      feeShareBps: r.fee_share_bps ?? r.max_fee_bps ?? p.feeShareBps,
      apiWalletId: r.api_wallet_id,
      apiWalletPublicKey: key.publicKeyHex,
      apiWalletExpiresAt: r.api_wallet_expired_at,
      address: p.address,
      chain: p.chain,
      connectedAt: Date.now(),
    },
  };
}
